-- Consolidated initial schema for SkillIssues.
--
-- This is the single source of truth for the database. It replaces the former
-- split between database/schema.sql and the database/migrations/001..006 pairs,
-- neither of which was ever applied by any runner.
--
-- Do not edit this file once it has been applied anywhere. Add a new migration.

-- +goose Up

-- ---------------------------------------------------------------------------
-- 1. Authentication and users
-- ---------------------------------------------------------------------------

-- Core user account record linked to a GitHub identity.
CREATE TABLE IF NOT EXISTS users (
  id                  SERIAL       PRIMARY KEY,
  github_id           TEXT         UNIQUE,
  username            TEXT         NOT NULL,
  name                TEXT,
  avatar_url          TEXT,
  github_access_token TEXT,
  created_at          TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- Case-insensitive uniqueness so PAT login and OAuth login resolve to one user.
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_username_lower ON users (lower(username));

-- Active sessions. `token` is a SHA-256 hash of the raw bearer token; the raw
-- token is never stored.
CREATE TABLE IF NOT EXISTS auth_sessions (
  token      TEXT        PRIMARY KEY,
  user_id    INTEGER     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider   TEXT        NOT NULL DEFAULT 'demo',
  expires_at TIMESTAMPTZ NOT NULL DEFAULT (now() + interval '7 days'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Ephemeral PKCE state for the GitHub OAuth handshake.
CREATE TABLE IF NOT EXISTS oauth_states (
  state         TEXT        PRIMARY KEY,
  code_verifier TEXT        NOT NULL,
  redirect_uri  TEXT        NOT NULL,
  expires_at    TIMESTAMPTZ NOT NULL DEFAULT (now() + interval '10 minutes'),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- 2. Developer profiles and preferences
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS developer_profiles (
  user_id             INTEGER  PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  bio                 TEXT     DEFAULT '',
  experience_level    TEXT     NOT NULL DEFAULT 'BEGINNER'
    CHECK (experience_level IN ('BEGINNER', 'INTERMEDIATE', 'ADVANCED')),
  target_level        TEXT     NOT NULL DEFAULT 'INTERMEDIATE'
    CHECK (target_level IN ('BEGINNER', 'INTERMEDIATE', 'ADVANCED')),
  progress_score      INTEGER  NOT NULL DEFAULT 18,
  completed_count     INTEGER  NOT NULL DEFAULT 0,
  demonstrated_skills TEXT[]   NOT NULL DEFAULT '{}',
  total_xp            INTEGER  NOT NULL DEFAULT 0,
  level               INTEGER  NOT NULL DEFAULT 1,
  badges              TEXT[]   NOT NULL DEFAULT '{}'
);

CREATE TABLE IF NOT EXISTS developer_preferences (
  user_id             INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  interests           TEXT[]  NOT NULL DEFAULT '{}',
  preferred_languages TEXT[]  NOT NULL DEFAULT '{}'
);

-- ---------------------------------------------------------------------------
-- 3. Repositories and the issue catalog
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS repositories (
  id               SERIAL      PRIMARY KEY,
  github_id        BIGINT      UNIQUE,
  full_name        TEXT        NOT NULL UNIQUE,
  url              TEXT        NOT NULL,
  description      TEXT        DEFAULT '',
  language         TEXT,
  stars            INTEGER     NOT NULL DEFAULT 0,
  license          TEXT,
  forkable         BOOLEAN     NOT NULL DEFAULT true,
  last_activity_at TIMESTAMPTZ,
  last_synced_at   TIMESTAMPTZ
);

-- Issues are retained when closed; closed state excludes them from the catalog
-- rather than deleting them.
CREATE TABLE IF NOT EXISTS issues (
  id                   SERIAL      PRIMARY KEY,
  github_id            BIGINT      UNIQUE,
  repository_id        INTEGER     NOT NULL REFERENCES repositories(id) ON DELETE CASCADE,
  number               INTEGER     NOT NULL,
  title                TEXT        NOT NULL,
  body                 TEXT        DEFAULT '',
  url                  TEXT        NOT NULL,
  state                TEXT        NOT NULL DEFAULT 'OPEN'
    CHECK (state IN ('OPEN', 'CLOSED')),
  difficulty_score     INTEGER     NOT NULL,
  difficulty           TEXT        NOT NULL
    CHECK (difficulty IN ('BEGINNER', 'INTERMEDIATE', 'ADVANCED')),
  required_skills      TEXT[]      NOT NULL DEFAULT '{}',
  technologies         TEXT[]      NOT NULL DEFAULT '{}',
  learning_tags        TEXT[]      NOT NULL DEFAULT '{}',
  comments             INTEGER     NOT NULL DEFAULT 0,
  has_difficulty_label BOOLEAN     NOT NULL DEFAULT false,
  author               TEXT,
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(repository_id, number)
);

CREATE TABLE IF NOT EXISTS saved_issues (
  user_id    INTEGER     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  issue_id   INTEGER     NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, issue_id)
);

-- ---------------------------------------------------------------------------
-- 4. Contributions and PR verification
-- ---------------------------------------------------------------------------

-- issue_id deliberately has no ON DELETE CASCADE: contribution history
-- outlives the issue it referenced.
CREATE TABLE IF NOT EXISTS contributions (
  id         SERIAL      PRIMARY KEY,
  user_id    INTEGER     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  issue_id   INTEGER     NOT NULL REFERENCES issues(id),
  pr_url     TEXT,
  pr_number  INTEGER,
  state      TEXT        NOT NULL DEFAULT 'STARTED'
    CHECK (state IN ('STARTED', 'PR_OPEN', 'PR_CLOSED', 'PR_MERGED', 'VERIFIED')),
  xp_awarded BOOLEAN     NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  merged_at  TIMESTAMPTZ
);

-- A user may re-attempt an issue, but only one attempt may be in STARTED at a time.
CREATE UNIQUE INDEX IF NOT EXISTS idx_contributions_user_issue_active
  ON contributions (user_id, issue_id)
  WHERE state = 'STARTED';

CREATE TABLE IF NOT EXISTS contribution_audit_log (
  id              SERIAL      PRIMARY KEY,
  contribution_id INTEGER     NOT NULL REFERENCES contributions(id) ON DELETE CASCADE,
  user_id         INTEGER     NOT NULL REFERENCES users(id),
  from_state      TEXT,
  to_state        TEXT        NOT NULL,
  event           TEXT        NOT NULL,
  metadata        JSONB,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- 5. Sync pipeline and GitHub rate-limit tracking
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS sync_state (
  repository_id          INTEGER     PRIMARY KEY REFERENCES repositories(id) ON DELETE CASCADE,
  last_synced_at         TIMESTAMPTZ,
  last_issue_sync_at     TIMESTAMPTZ,
  last_issue_update_seen TIMESTAMPTZ,
  priority               TEXT        NOT NULL DEFAULT 'MEDIUM'
    CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
  sync_status            TEXT        NOT NULL DEFAULT 'PENDING'
    CHECK (sync_status IN ('PENDING', 'RUNNING', 'DONE', 'FAILED')),
  failure_count          INTEGER     NOT NULL DEFAULT 0,
  next_sync_at           TIMESTAMPTZ,
  rate_limit_limit       INTEGER,
  rate_limit_remaining   INTEGER,
  rate_limit_used        INTEGER,
  rate_limit_reset_at    TIMESTAMPTZ,
  rate_limit_cost        INTEGER
);

-- Deduplication log for GitHub webhook deliveries.
CREATE TABLE IF NOT EXISTS webhook_events (
  delivery_id  TEXT        PRIMARY KEY,
  event_name   TEXT        NOT NULL,
  processed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- 6. Indexes
-- ---------------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS repositories_language_idx ON repositories(language);
CREATE INDEX IF NOT EXISTS repositories_stars_idx    ON repositories(stars DESC);

CREATE INDEX IF NOT EXISTS issues_state_idx      ON issues(state);
CREATE INDEX IF NOT EXISTS issues_difficulty_idx ON issues(difficulty);
CREATE INDEX IF NOT EXISTS issues_updated_idx    ON issues(updated_at DESC);
CREATE INDEX IF NOT EXISTS issues_repository_idx ON issues(repository_id);

-- GIN indexes serve array containment (@>) filtering on skills and technologies.
CREATE INDEX IF NOT EXISTS issues_required_skills_idx ON issues USING GIN(required_skills);
CREATE INDEX IF NOT EXISTS issues_technologies_idx    ON issues USING GIN(technologies);
CREATE INDEX IF NOT EXISTS issues_learning_tags_idx   ON issues USING GIN(learning_tags);

CREATE INDEX IF NOT EXISTS contributions_user_idx  ON contributions(user_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS contributions_issue_idx ON contributions(issue_id);
CREATE INDEX IF NOT EXISTS saved_issues_user_idx   ON saved_issues(user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS sync_state_priority_idx  ON sync_state(priority, last_synced_at NULLS FIRST);
CREATE INDEX IF NOT EXISTS sync_state_next_sync_idx ON sync_state(next_sync_at);

CREATE INDEX IF NOT EXISTS audit_log_contribution_idx
  ON contribution_audit_log(contribution_id, created_at DESC);

-- +goose Down

DROP TABLE IF EXISTS webhook_events;
DROP TABLE IF EXISTS sync_state;
DROP TABLE IF EXISTS contribution_audit_log;
DROP TABLE IF EXISTS contributions;
DROP TABLE IF EXISTS saved_issues;
DROP TABLE IF EXISTS issues;
DROP TABLE IF EXISTS repositories;
DROP TABLE IF EXISTS developer_preferences;
DROP TABLE IF EXISTS developer_profiles;
DROP TABLE IF EXISTS oauth_states;
DROP TABLE IF EXISTS auth_sessions;
DROP TABLE IF EXISTS users;
